import{_ as u,a0 as i,w as r,s as a,ao as p,I as n,a1 as s,A as l,x as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"如何在 Ubuntu 和其他 Linux 發行版中創建照片幻燈片 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 和其他 Linux 發行版中創建照片幻燈片 | LCTT (201809) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 和其他 Linux 發行版中創建照片幻燈片 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 和其他 Linux 發行版中創建照片幻燈片 | LCTT (201809) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201809/20180831 How to Create a Slideshow of Photos in Ubuntu 18.04 and other Linux Distributions","title":"如何在 Ubuntu 和其他 Linux 發行版中創建照片幻燈片","tag":"201809","desc":""},"relativePath":"201809/20180831 How to Create a Slideshow of Photos in Ubuntu 18.04 and other Linux Distributions.md","filePath":"[post].md"}'),d={name:"201809/20180831 How to Create a Slideshow of Photos in Ubuntu 18.04 and other Linux Distributions.md"};function h(b,t,f,m,w,x){const e=i("Link");return r(),a("div",null,[t[19]||(t[19]=p('<h1 id="如何在-ubuntu-和其他-linux-發行版中創建照片幻燈片" tabindex="-1">如何在 Ubuntu 和其他 Linux 發行版中創建照片幻燈片 <a class="header-anchor" href="#如何在-ubuntu-和其他-linux-發行版中創建照片幻燈片" aria-label="Permalink to “如何在 Ubuntu 和其他 Linux 發行版中創建照片幻燈片”">​</a></h1><p>創建照片幻燈片只需點擊幾下。以下是如何在 Ubuntu 18.04 和其他 Linux 發行版中製作照片幻燈片。</p><p><img src="https://4bds6hergc-flywheel.netdna-ssl.com/wp-content/uploads/2018/08/Create-photos-Slideshow-Linux.png" alt="How to create slideshow of photos in Ubuntu Linux"></p><p>想像一下，你的朋友和親戚正在拜訪你，並請你展示最近的活動/旅行照片。</p><p>你將照片保存在計算機上，並整齊地放在單獨的文件夾中。你邀請計算機附近的所有人。你進入該文件夾​​，單擊其中一張圖片，然後按箭頭鍵逐個顯示照片。</p><p>但那太累了！如果這些圖片每隔幾秒自動更改一次，那將會好很多。</p><p>這稱之為幻燈片，我將向你展示如何在 Ubuntu 中創建照片幻燈片。這能讓你在文件夾中循環播放圖片並以全屏模式顯示它們。</p><h3 id="在-ubuntu-18-04-和其他-linux-發行版中創建照片幻燈片" tabindex="-1">在 Ubuntu 18.04 和其他 Linux 發行版中創建照片幻燈片 <a class="header-anchor" href="#在-ubuntu-18-04-和其他-linux-發行版中創建照片幻燈片" aria-label="Permalink to “在 Ubuntu 18.04 和其他 Linux 發行版中創建照片幻燈片”">​</a></h3><p>雖然有幾種圖像瀏覽器可以做到，但我將向你展示大多數發行版中應該提供的兩種最常用的工具。</p><h4 id="方法-1-使用-gnome-默認圖像瀏覽器瀏覽照片幻燈片" tabindex="-1">方法 1：使用 GNOME 默認圖像瀏覽器瀏覽照片幻燈片 <a class="header-anchor" href="#方法-1-使用-gnome-默認圖像瀏覽器瀏覽照片幻燈片" aria-label="Permalink to “方法 1：使用 GNOME 默認圖像瀏覽器瀏覽照片幻燈片”">​</a></h4><p>如果你在 Ubuntu 18.04 或任何其他發行版中使用 GNOME，那麼你很幸運。Gnome 的默認圖像瀏覽器，Eye of GNOME，能夠在當前文件夾中顯示圖片的幻燈片。</p><p>只需單擊其中一張圖片，你將在程序的右上角菜單中看到設置選項。它看起來像堆疊在一起的三條橫欄。</p><p>你會在這裏看到幾個選項。勾選幻燈片選項，它將全屏顯示圖像。</p><p><img src="https://4bds6hergc-flywheel.netdna-ssl.com/wp-content/uploads/2018/08/create-slideshow-photos-ubuntu-gnome.jpeg" alt="How to create slideshow of photos in Ubuntu Linux"></p><p>默認情況下，圖像以 5 秒的間隔變化。你可以進入 “Preferences -&gt; Slideshow” 來更改幻燈片放映間隔。</p><p><img src="https://4bds6hergc-flywheel.netdna-ssl.com/wp-content/uploads/2018/08/change-slideshow-interval-gnome-image.jpeg" alt="change slideshow interval in Ubuntu"></p><h4 id="方法-2-使用-shotwell-photo-manager-進行照片幻燈片放映" tabindex="-1">方法 2：使用 Shotwell Photo Manager 進行照片幻燈片放映 <a class="header-anchor" href="#方法-2-使用-shotwell-photo-manager-進行照片幻燈片放映" aria-label="Permalink to “方法 2：使用 Shotwell Photo Manager 進行照片幻燈片放映”">​</a></h4>',17)),n("p",null,[s(e,{href:"https://wiki.gnome.org/Apps/Shotwell"},{default:l(()=>[...t[0]||(t[0]=[o("Shotwell",-1)])]),_:1}),t[2]||(t[2]=o(" 是一款流行的 ",-1)),s(e,{href:"https://itsfoss.com/linux-photo-management-software/"},{default:l(()=>[...t[1]||(t[1]=[o("Linux 照片管理程序",-1)])]),_:1}),t[3]||(t[3]=o("。適用於所有主要的 Linux 發行版。",-1))]),t[20]||(t[20]=n("p",null,"如果尚未安裝，請在你的發行版軟件中心中搜索 Shotwell 並安裝。",-1)),t[21]||(t[21]=n("p",null,"Shotwell 的運行略有不同。如果你在 Shotwell Viewer 中直接打開照片，則不會看到首選項或者幻燈片的選項。",-1)),t[22]||(t[22]=n("p",null,"對於幻燈片放映和其他選項，你必須打開 Shotwell 並導入包含這些圖片的文件夾。導入文件夾後，從左側窗格中選擇該文件夾，然後單擊菜單中的 “View”。你應該在此處看到幻燈片選項。只需單擊它即可創建所選文件夾中所有圖像的幻燈片。",-1)),t[23]||(t[23]=n("p",null,[n("img",{src:"https://4bds6hergc-flywheel.netdna-ssl.com/wp-content/uploads/2018/08/create-slideshow-photos-shotwell.jpeg",alt:"How to create slideshow of photos in Ubuntu Linux"})],-1)),t[24]||(t[24]=n("p",null,"你還可以更改幻燈片設置。當圖像以全屏顯示時，將顯示此選項。只需將鼠標懸停在底部，你就會看到一個設置選項。",-1)),t[25]||(t[25]=n("h4",{id:"創建照片幻燈片很容易",tabindex:"-1"},[o("創建照片幻燈片很容易 "),n("a",{class:"header-anchor",href:"#創建照片幻燈片很容易","aria-label":"Permalink to “創建照片幻燈片很容易”"},"​")],-1)),t[26]||(t[26]=n("p",null,"如你所見，在 Linux 中創建照片幻燈片非常簡單。我希望你覺得這個簡單的提示有用。如果你有任何問題或建議，請在下面的評論欄告訴我們。",-1)),t[27]||(t[27]=n("hr",null,null,-1)),n("p",null,[t[5]||(t[5]=o("via: ",-1)),s(e,{href:"https://itsfoss.com/photo-slideshow-ubuntu/"},{default:l(()=>[...t[4]||(t[4]=[o("https://itsfoss.com/photo-slideshow-ubuntu/",-1)])]),_:1})]),n("p",null,[t[10]||(t[10]=o("作者：",-1)),s(e,{href:"https://itsfoss.com/author/abhishek/"},{default:l(()=>[...t[6]||(t[6]=[o("Abhishek Prakash",-1)])]),_:1}),t[11]||(t[11]=o(" 選題：",-1)),s(e,{href:"https://github.com/lujun9972"},{default:l(()=>[...t[7]||(t[7]=[o("lujun9972",-1)])]),_:1}),t[12]||(t[12]=o(" 譯者：",-1)),s(e,{href:"https://github.com/geekpi"},{default:l(()=>[...t[8]||(t[8]=[o("geekpi",-1)])]),_:1}),t[13]||(t[13]=o(" 校對：",-1)),s(e,{href:"https://github.com/wxy"},{default:l(()=>[...t[9]||(t[9]=[o("wxy",-1)])]),_:1})]),n("p",null,[t[16]||(t[16]=o("本文由 ",-1)),s(e,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[14]||(t[14]=[o("LCTT",-1)])]),_:1}),t[17]||(t[17]=o(" 原創編譯，",-1)),s(e,{href:"https://linux.cn/"},{default:l(()=>[...t[15]||(t[15]=[o("Linux中國",-1)])]),_:1}),t[18]||(t[18]=o(" 榮譽推出",-1))])])}const C=u(d,[["render",h]]);export{T as __pageData,C as default};
